sql_generado:
SELECT COUNT(*) AS total_devoluciones 
FROM transacciones_financieras tf 
WHERE tf.tipo = 'devolucion' AND EXTRACT(MONTH FROM tf.fecha_transaccion) = EXTRACT(MONTH FROM CURRENT_DATE);

SELECT COALESCE(SUM(CASE WHEN tf.tipo = 'gasto_operativo' THEN ABS(tf.monto) ELSE 0 END), 0) AS gastos_corporativos FROM transacciones_financieras tf 
JOIN reservas r ON r.reserva_id = tf.reserva_id 
JOIN clientes c ON c.cliente_id = r.cliente_id WHERE EXTRACT(MONTH FROM tf.fecha_transaccion) = EXTRACT(MONTH FROM CURRENT_DATE) AND c.segmento = 'corporativo';

SELECT ROUND(AVG(tf.monto), 2) AS ingreso_promedio_diario 
FROM transacciones_financieras tf 
WHERE EXTRACT(MONTH FROM tf.fecha_transaccion) = EXTRACT(MONTH FROM CURRENT_DATE);

SELECT COUNT(*) AS total_reservas, r.estado 
FROM reservas r 
GROUP BY r.estado;

SELECT COUNT(*) AS total_reservas 
FROM reservas r 
WHERE EXTRACT(DOW FROM fecha_reserva) IN (0,6) AND fecha_reserva < CURRENT_DATE;
